import os, time
pids = []
for _ in range(15):
    try:
        pid = os.fork()
    except OSError:
        break
    if pid == 0:
        time.sleep(3)
        os._exit(0)
    pids.append(pid)
for p in pids:
    os.waitpid(p, 0)
print('hog 0 forked', len(pids))

